<?php declare(strict_types=1);
use Kulturhus\Verein\{Finance,Settings,SettingsSchema,OutgoingInvoices};
require_once __DIR__.'/bank-group-fixture.php';
function ownPaymentReturnIssuedCase(PDO $db,string $actor,string $tag,string $account=''):array
{
    ownBankGroupDatabase($db);$key=static fn()=>bin2hex(random_bytes(16));$finance=new Finance($db,$actor);$account=$account!==''?$account:$finance->createAccount('Own actual issued return bank','offline','1000','2020-01-01');$saved=$finance->accountSettings($account);$finance->saveAccountSettings($account,(int)$saved['version'],true,'18000',true,true);$settings=new Settings($db,$actor);
    foreach(['club'=>['name'=>'Own original invoice association','street'=>'Own road1','postcode'=>'00000','city'=>'Own town','email'=>'office@example.invalid'],'tax'=>['number'=>'00/000/00000'],'bank'=>['iban'=>'DE89370400440532013000','holder'=>'Own original invoice association','account_id'=>$account]]as$section=>$values){$current=$settings->section($section);$data=array_replace($current['data'],$values);if($data!==$current['data'])$settings->save($section,$data,(int)$current['version']);}
    $invoices=new OutgoingInvoices($db,$actor);$data=['invoice_format'=>'pdf','domestic_confirmed'=>'1','seller_contact'=>'Own original office','buyer_name'=>'Own actual original customer','buyer_street'=>'Own road2','buyer_postcode'=>'00000','buyer_city'=>'Own town','buyer_email'=>'customer@example.invalid','buyer_reference'=>'','description'=>'Own valid original service '.$tag,'note'=>'Own original demand stays valid','vat_reason'=>'Steuerbefreiung nach §19 UStG.','document_date'=>'2026-01-01','delivery_date'=>'2026-01-01','due_date'=>'2026-01-05','category'=>'rooms','contact_id'=>'','payment_account'=>$account,'positions'=>[['description'=>'Own original service','quantity'=>'1','unit'=>'C62','unit_gross'=>'100','tax_rate'=>'0','sphere'=>'3','account'=>'42030']]];
    $invoice=$invoices->save('',0,$data,$key());$invoices->review($invoice,1);$entry=$invoices->issue($invoice,2);$finance->recordPayment($entry,(int)$finance->entry($entry)['version'],$account,'2026-01-10');$source=$finance->allocations($entry)[0]['transaction_id'];$returned=$finance->createTransaction(['account'=>$account,'direction'=>'expense','amount'=>'100','booked_on'=>'2026-01-11','description'=>'Own actual full returned invoice payment '.$tag],$key());
    $q=$db->prepare('SELECT club_id FROM actors WHERE id=?');$q->execute([$actor]);$club=$q->fetchColumn();return compact('club','actor','finance','account','invoices','invoice','entry','source','returned');
}
